<script>
 import PowerTrend from "./PowerTrend.svelte";
 import {usePresentation} from "$lib/presentation.svelte.js";
 import SimulationNotice from "./SimulationNotice.svelte";
 import {invalidateAll} from '$app/navigation';import {onMount} from 'svelte';import Icon from './Icon.svelte';import EnergyFlow from './EnergyFlow.svelte';import HistoryChart from './HistoryChart.svelte';import SolarHome from './SolarHome.svelte';import BatteryGauge from './BatteryGauge.svelte';import {formatValue,formatTime} from '$lib/energy';
 let {data:incoming,preview=false}=$props();
 const presentation=usePresentation(()=>incoming);let data=$derived(presentation.data);
let refreshing=$state(false);let refreshError=$state(false);
 let metrics=$derived(data.snapshot?.metrics || {});
 let stale=$derived(Object.values(metrics).some(m=>m?.freshness==='stale'||m?.freshness==='invalid'));
 const messages={awaiting_installation:['Your system is being linked','Your account is ready. GridUbuntu is confirming which solar installation belongs to your residence.'],not_configured:['Awaiting connection','Your residence is registered. The GridUbuntu team is preparing its secure energy connection.'],no_assignment:['Your invitation is active','A residence has not been assigned to this account yet. Please contact your GridUbuntu team.'],database_unavailable:['Your residence is temporarily unavailable','We could not load your assigned residence. Try again or contact support.'],unavailable:['Energy connection unavailable','We could not retrieve the latest provider data. No current readings are being assumed.'],awaiting_verification:['Connection awaiting verification','GridUbuntu is checking the installation’s readings against Victron before making them available here.'],partial:['Some readings are unavailable','Part of the provider response could not be retrieved. Available readings retain their original reporting times.']};
 async function refresh(){if(preview)return;refreshing=true;refreshError=false;try{await invalidateAll();}catch{refreshError=true;}finally{refreshing=false;}}
 onMount(()=>{if(preview)return;const id=setInterval(()=>{if(document.visibilityState==='visible')refresh();},60000);return()=>clearInterval(id);});
 function power(m){return m?.value===undefined||m?.value===null?'—':formatValue(m.value/1000,'',2);}
</script>
{#if data.simulated}<SimulationNotice/>{/if}
<div class="page-heading"><div><div class="breadcrumb">MY RESIDENCE <span>/</span> OVERVIEW</div><h1>{data.node?.display_name || 'Your energy overview'}</h1><p>{data.node?.reference || 'Residence assignment pending'} <span>·</span> {data.node?.location_label || 'Zimbabwe'} <span>·</span> {preview?'Illustrative system':'Residential solar & storage'}</p></div><button class="refresh-button" onclick={refresh} disabled={refreshing||preview}><Icon name="refresh" size={16}/>{refreshing?'Refreshing…':'Refresh'}</button></div>
<div class="connection-line"><span class:stale class:connected={data.status==='connected'&&!stale} class="connection-badge"><i></i>{data.simulated?'Updating':preview?'Sample readings':stale?'Readings delayed':data.status==='connected'?'Provider connected':data.status==='partial'?'Partial connection':data.status==='awaiting_installation'?'System selection pending':'Connection pending'}</span><span>{preview?'Illustrative reporting time':'Oldest displayed reading'}: {formatTime(data.snapshot?.reportedAt)}</span></div>
{#if messages[data.status]}<div class="notice"><Icon name="info"/><div><strong>{messages[data.status][0]}</strong><p>{messages[data.status][1]}</p></div></div>{/if}{#if stale}<div class="notice warning" role="status"><Icon name="info"/><div><strong>These readings may be out of date.</strong><p>At least one reading is more than 15 minutes old or has an invalid future timestamp. Check each reading’s reporting time.</p></div></div>{/if}{#if refreshError}<p class="form-error" role="alert">The page could not refresh. Try again.</p>{/if}
<div class="energy-story-grid">
 <section class="panel home-energy-panel">
  <div class="panel-heading"><div><span class="overline">YOUR HOME, POWERED BY SUNSHINE</span><h2>Today's energy</h2></div><span class="panel-tag">Today · CAT</span></div>
  <div class="home-energy-scene"><div class="daily-energy-number"><span>Solar generated</span><strong>{formatValue(data.history?.totals?.solar,'',2)} <small>kWh</small></strong><p>Energy captured from the sun today</p></div><SolarHome/></div>
  <div class="home-daily-summary"><div><span><i class="usage-key"></i>Home used</span><strong>{formatValue(data.history?.totals?.consumption,'',2)} <small>kWh</small></strong></div><div><span><Icon name="grid" size={14}/>Grid supplied</span><strong>{formatValue(data.history?.totals?.gridImport,'',2)} <small>kWh</small></strong></div><div><span><Icon name="sun" size={14}/>Sent to grid</span><strong>{formatValue(data.history?.totals?.gridExport,'',2)} <small>kWh</small></strong></div></div>
  <p class="energy-help">kWh is the amount of energy generated or used over time. {preview?'Illustrative values for this design preview.':data.stored?'Stored history may contain gaps.':data.simulated?'The current hour is still in progress.':'Totals use available provider data.'}</p>
 </section>
 <BatteryGauge {metrics}/>
</div>
<section class="instant-readings" aria-label="Latest reported power"><div class="instant-caption"><span class="overline">RIGHT NOW</span><span>Latest reported power</span></div><div class="instant-value"><span class="instant-symbol"><Icon name="sun" size={20}/></span><div><span>Solar producing</span><strong>{power(metrics.solar)} <small>kW</small></strong><small>{metrics.solar?formatTime(metrics.solar.reportedAt):'Not reported'}</small></div></div><div class="instant-value"><span class="instant-symbol"><Icon name="home" size={20}/></span><div><span>Home using</span><strong>{power(metrics.consumption)} <small>kW</small></strong><small>{metrics.consumption?formatTime(metrics.consumption.reportedAt):'Not reported'}</small></div></div><p>kW tells you how much power is being produced or used at a moment in time.</p></section>
{#if data.simulated}<PowerTrend reportedAt={data.snapshot?.reportedAt}/>{/if}
<div class="visual-insights-grid">
 <section class="panel flow-panel"><div class="panel-heading"><div><span class="overline">YOUR CONNECTED HOME</span><h2>Your energy at a glance</h2></div><span class="panel-tag">{preview?'Sample':'Latest reported'}</span></div><EnergyFlow {metrics} simulated={data.simulated}/></section>
<section class="panel history-panel"><div class="panel-heading"><div><span class="overline">GENERATION & CONSUMPTION</span><h2>Your energy through the day</h2></div><a class="quiet-link" href={preview?'/portal-preview?view=history':'/portal/history'}>View history →</a></div><HistoryChart history={data.history}/></section>
</div><div class="bottom-panels"><section class="panel"><div class="panel-heading"><div><span class="overline">INSTALLATION HEALTH</span><h2>Stay connected to your system</h2></div><Icon name="system"/></div><div class="health-row"><span>Data connection</span><strong>{data.simulated?'Responding':preview?'Sample system':data.status==='connected'?'Responding':data.status==='partial'?'Partially responding':'Awaiting connection'}</strong></div><div class="health-row"><span>Device information</span><strong>{data.devices?.length?`${data.devices.length} devices reported`:'Not yet available'}</strong></div><a class="panel-link" href={preview?'/portal-preview?view=system':'/portal/system'}>View system details <span>→</span></a></section><section class="community-note"><span class="overline">THE POWER OF UBUNTU</span><h2>Your energy,<br/>part of something bigger.</h2><p>Understanding how we generate and use power is the first step towards a stronger energy community.</p><a href="/about">Why GridUbuntu <span>↗</span></a></section></div>
